# Shared books without an editor: sharing takes doesn't lock and can be repeated; a co-narrator's line pack reaches the
# lead through the shared folder; anyone can bring in everyone's takes (theirs shared first, no line twice); old Editor
# entries become Outside.
from _env import *
import asyncio, subprocess, sys
from playwright.async_api import async_playwright
srv = subprocess.Popen([sys.executable,"-m","http.server","8633","-d",ROOT],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
U="http://localhost:8633/index.html?test"
C = "Booth.state.audio.tracks.map((t,i)=>'T'+(i+1)+'('+((Booth._test.trackSet()[i]||{}).name||'')+'):'+t.clips.map(c=>'['+c.at.toFixed(2)+'–'+(c.at+c.dur).toFixed(2)+(c.line?' L'+c.line.r:'')+']').join('')).join('  ')"
async def main():
  async with async_playwright() as p:
    b = await p.chromium.launch(executable_path=CHROME, args=["--no-sandbox","--use-fake-device-for-media-stream","--use-fake-ui-for-media-stream","--autoplay-policy=no-user-gesture-required"])
    ctx = await b.new_context(permissions=["microphone"], viewport={"width":1440,"height":900}); pg = await ctx.new_page()
    ERR=[]; errs=[]; pg.on("pageerror", lambda e: errs.append(str(e))); pg.on("console", lambda m: m.type=="error" and errs.append("console:"+m.text))
    pg.on("dialog", lambda d: asyncio.ensure_future(d.accept()))
    SH = "Store.pickSharedFolder = async () => (await navigator.storage.getDirectory()).getDirectoryHandle('SharedBook', {create:true});"
    await pg.goto(U+"#/import"); await pg.wait_for_timeout(500); await pg.evaluate(SH)
    await pg.set_input_files("#file",FIX+"/duet.docx"); await pg.wait_for_selector("#create")
    await pg.fill("#it","Shared Duet"); await pg.click("#create"); await pg.wait_for_selector("table.ch"); await pg.wait_for_timeout(400)
    bid = await pg.evaluate("Store.books[0].id")
    await pg.evaluate("(()=>{const b=Store.books[0]; b.parts=Object.assign({}, b.parts, {n:'Anne', f:'Anne', m:'Jack'}); Store.settings.narrators=[{name:'Anne',pace:4035},{name:'Jack',pace:2000},{name:'Eddie',pace:1}]; Store.saveBook(b,true);})()")
    await pg.goto(U+"#/library"); await pg.goto(U+f"#/book/{bid}"); await pg.wait_for_timeout(600); await pg.evaluate(SH)
    await pg.evaluate("document.querySelector('#sharedc').open=true"); await pg.click("#shsetup"); await pg.wait_for_timeout(800)
    # an old Editor entry: it becomes Outside when the owner opens the book page
    await pg.evaluate("(()=>{const b=Store.books[0]; b.sharedPeople=[{name:'Anne',role:'lead',edits:true},{name:'Jack',role:'narrator'},{name:'Eddie',role:'editor'}]; Store.saveBook(b,true);})()")
    await pg.goto(U+"#/library"); await pg.goto(U+f"#/book/{bid}"); await pg.wait_for_timeout(900)
    ppl = await pg.evaluate("JSON.stringify(Store.books[0].sharedPeople)"); print("people:", ppl)
    if '"editor"' in ppl or '"edits"' in ppl: ERR.append("Editor entry not migrated to Outside")
    await pg.evaluate("document.querySelector('#sharedc').open=true"); await pg.wait_for_timeout(300)
    opts = await pg.evaluate("[...document.querySelectorAll('#sharedc select option')].map(o=>o.textContent)"); print("roles:", sorted(set(opts)))
    if any("Editor" in o for o in opts) or await pg.query_selector("[data-shedit]"): ERR.append("Editor role or Also edits still offered")
    # Jack records his lines and sends them: the pack goes to the shared folder as well as the Library
    await pg.evaluate("localStorage.setItem('lr-me','Jack')"); await pg.goto(U+"#/library"); await pg.wait_for_timeout(300)
    await pg.goto(U+f"#/booth/{bid}/0"); await pg.wait_for_selector("#booth-dock"); await pg.wait_for_timeout(800); await pg.evaluate(SH)
    n = await pg.evaluate("Booth._test.myRuns().length")
    await pg.evaluate("Booth.state.prerollSec=0"); await pg.keyboard.press("r"); await pg.wait_for_timeout(1200*n+1500); await pg.keyboard.press("s"); await pg.wait_for_timeout(800)
    await pg.evaluate("(()=>{const rs=Booth._test.myRuns(); Booth.state.audio.anchors=[]; rs.forEach((x,k)=>{const t0=0.35+1.2*k; Booth.state.audio.anchors.push([t0+0.15, x.from+1]); Booth.state.audio.anchors.push([t0+0.6, x.to+1]);});})()")
    await pg.evaluate("Store.sharedHandle(Store.books[0], true)")
    await pg.evaluate("Booth._test.sendLines()"); await pg.wait_for_function("!Booth.state.busy", timeout=60000); await pg.wait_for_timeout(500)
    shl = await pg.evaluate("(async()=>{try{const b=Store.books[0]; const d=await Store.sharedLinesDir(b, b.chapters[0], 'Jack', false); const f=await (await d.getFileHandle('lines.json')).getFile(); return JSON.parse(await f.text()).lines.length;}catch(e){return 'none: '+e.message}})()")
    print("line pack in the shared folder:", shl, "of", n)
    if shl != n: ERR.append("line pack not in the shared folder")
    # take the Library copy away: Anne must get the lines from the shared folder (as a co-narrator in another Library would)
    await pg.evaluate("(async()=>{const b=Store.books[0]; const B=await Store.root.getDirectoryHandle('Books'); const f=await B.getDirectoryHandle(b.folder); await f.removeEntry('duet',{recursive:true});})()")
    await pg.evaluate("localStorage.setItem('lr-me','Anne')"); await pg.goto(U+"#/library"); await pg.wait_for_timeout(300)
    await pg.goto(U+f"#/booth/{bid}/0"); await pg.wait_for_selector("#booth-dock"); await pg.evaluate(SH); await pg.evaluate("Store.sharedHandle(Store.books[0], true)"); await pg.wait_for_timeout(2500)
    got = await pg.evaluate("(Booth._test.duetData().Jack||{lines:[]}).lines.length"); print("Anne got Jack's lines:", got)
    if got != n: ERR.append("lead didn't get the lines from the shared folder")
    await pg.evaluate("Booth.state.prerollSec=0"); await pg.keyboard.press("r"); await pg.wait_for_timeout(2500); await pg.keyboard.press("s"); await pg.wait_for_timeout(800)
    await pg.evaluate("Booth._test.spliceAll && Booth._test.spliceAll()"); await pg.wait_for_timeout(1500)
    print("Anne's chapter:", await pg.evaluate(C))
    await pg.evaluate("Booth.state.side=null; Booth.state.tab='shared'; Booth._test.act('tools')"); await pg.wait_for_timeout(900)
    tab = await pg.evaluate("document.querySelector('#sh-body').innerText.replace(/\\n+/g,' | ')"); print("shared tab:", tab)
    if "Share my takes" not in tab or "Editor" in tab: ERR.append("shared tab wording")
    await pg.click("[data-p='shsend']"); await pg.wait_for_timeout(500); await pg.wait_for_function("!Booth.state.busy", timeout=60000); await pg.wait_for_timeout(500)
    s1 = await pg.evaluate("Booth.state.chap.sent.Anne"); print("shared:", s1)
    await pg.keyboard.press("r"); await pg.wait_for_timeout(600); rec = await pg.evaluate("!!Booth.state.rec"); await pg.keyboard.press("s"); await pg.wait_for_timeout(600)
    print("can record after sharing:", rec)
    if not rec: ERR.append("chapter locked after sharing")
    await pg.evaluate("Booth._test.sendToShared(true)"); await pg.wait_for_function("!Booth.state.busy", timeout=60000); await pg.wait_for_timeout(300)
    s2 = await pg.evaluate("Booth.state.chap.sent.Anne"); print("shared again:", s2)
    if not s2 or s2 == s1: ERR.append("couldn't share again")
    # Jack: the done card offers Share my takes, then he brings everyone in
    await pg.evaluate("localStorage.setItem('lr-me','Jack')"); await pg.goto(U+"#/library"); await pg.wait_for_timeout(300)
    await pg.goto(U+f"#/booth/{bid}/0"); await pg.wait_for_selector("#booth-dock"); await pg.wait_for_timeout(1200); await pg.evaluate(SH); await pg.evaluate("Store.sharedHandle(Store.books[0], true)")
    await pg.evaluate("Booth._test.chapterComplete()"); await pg.wait_for_timeout(1500)
    dlg = await pg.evaluate("[...document.querySelectorAll('.overlay button')].map(b=>b.innerText).join(' / ')"); print("done dialog:", dlg)
    if "Share my takes" not in dlg or "Editor" in dlg: ERR.append("done card should offer Share my takes")
    await pg.evaluate("document.querySelectorAll('.overlay').forEach(o=>o.remove())")
    await pg.evaluate("Booth.state.side=null; Booth.state.tab='shared'; Booth._test.act('tools')"); await pg.wait_for_timeout(900)
    await pg.click("[data-p='shin']"); await pg.wait_for_timeout(500); await pg.wait_for_function("!Booth.state.busy", timeout=90000); await pg.wait_for_timeout(900)
    tl = await pg.evaluate(C); print("Jack's assembled timeline:", tl)
    js = await pg.evaluate("Booth.state.chap.sent.Jack"); print("Jack's own takes shared first:", js)
    if not js: ERR.append("bringing in didn't share Jack's takes first")
    if not await pg.evaluate("!!Booth.state.audio.assembled"): ERR.append("timeline not marked assembled")
    jl = await pg.evaluate("Booth.state.audio.tracks.flatMap(t=>t.clips).filter(c=>c.line&&c.line.r==='Jack').length"); print("Jack's lines placed:", jl, "of", n)
    if jl > n: ERR.append("Jack's lines came in twice (from Anne's share and his own)")
    tab = await pg.evaluate("document.querySelector('#sh-body').innerText.replace(/\\n+/g,' | ')"); print("after:", tab)
    if "built from everyone's shared takes" not in tab or await pg.query_selector("[data-p='shsend']"): ERR.append("assembled timeline should not offer sharing on")
    await pg.keyboard.press("r"); await pg.wait_for_timeout(500); print("can record (not locked):", await pg.evaluate("!!Booth.state.rec")); await pg.keyboard.press("s"); await pg.wait_for_timeout(400)
    print("ERR:", ERR); print("ERRORS:", errs); await b.close()
asyncio.run(main()); srv.terminate()
